import * as React from 'react';
import { expect, it, vi } from 'vitest';
import { render, fireEvent, screen, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

it('controlled preventDefault still clears errors/validates', () => {
  const validate = vi.fn(() => null);
  function App() {
    const [v, setV] = React.useState('');
    return (
      <Form errors={{ message: 'Server error' }}>
        <Field.Root name="message" validationMode="onChange" validate={validate}>
          <Field.Control value={v} onValueChange={setV} />
          <Field.Error />
        </Field.Root>
      </Form>
    );
  }
  render(<App />);
  const control = screen.getByRole<HTMLInputElement>('textbox');
  control.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
  fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
  console.log('PD validate calls', validate.mock.calls.length, 'server error present', !!screen.queryByText('Server error'));
});

it('reset of required controlled field in onChange mode', () => {
  let setOuter: any;
  function App() {
    const [v, setV] = React.useState('init');
    setOuter = setV;
    return (
      <Field.Root data-testid="root" validationMode="onChange">
        <Field.Control required value={v} onValueChange={setV} />
        <Field.Error match="valueMissing">Required</Field.Error>
      </Field.Root>
    );
  }
  render(<App />);
  act(() => setOuter(''));
  console.log('reset-from-init: invalid', screen.getByTestId('root').getAttribute('data-invalid'), 'Required shown', !!screen.queryByText('Required'));
});

it('async load of initial value marks dirty', () => {
  let setOuter: any;
  const validate = vi.fn(() => 'err');
  function App() {
    const [v, setV] = React.useState('');
    setOuter = setV;
    return (
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control value={v} onValueChange={setV} />
        <Field.Error />
      </Field.Root>
    );
  }
  render(<App />);
  act(() => setOuter('loaded'));
  const r = screen.getByTestId('root');
  console.log('async load: dirty', r.getAttribute('data-dirty'), 'invalid', r.getAttribute('data-invalid'), 'validate calls', validate.mock.calls.length);
});

it('uncontrolled cancel', () => {
  const validate = vi.fn((v: any) => (v === 'a' ? null : 'bad'));
  render(
    <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
      <Field.Control defaultValue="" onValueChange={(v, d) => { if (v === 'a') d.cancel(); }} />
      <Field.Error />
    </Field.Root>,
  );
  const c = screen.getByRole<HTMLInputElement>('textbox');
  fireEvent.change(c, { target: { value: 'x' } });
  fireEvent.change(c, { target: { value: 'a' } });
  const r = screen.getByTestId('root');
  console.log('cancel: dom', c.value, 'dirty', r.getAttribute('data-dirty'), 'filled', r.getAttribute('data-filled'), 'invalid', r.getAttribute('data-invalid'), 'err', screen.queryByText('bad') ? 'bad shown' : 'none');
});

it('controlled rejected keystroke with stale onChange validation', () => {
  const validate = vi.fn(() => null);
  function App() {
    const [v, setV] = React.useState('abc');
    return (
      <Form errors={{ message: 'Server error' }}>
        <Field.Root name="message" validationMode="onChange" validate={validate}>
          <Field.Control value={v} onValueChange={(n) => setV(n.toUpperCase())} />
          <Field.Error />
        </Field.Root>
      </Form>
    );
  }
  render(<App />);
  const c = screen.getByRole<HTMLInputElement>('textbox');
  fireEvent.change(c, { target: { value: 'abC' } });
  console.log('uppercase same: validate', validate.mock.calls.length, 'server err', !!screen.queryByText('Server error'), c.value);
});
